import tempfile,os,subprocess
code="'use strict';
const base='http://127.0.0.1:17448';
const get=async(u)=>{const r=await fetch(u,{signal:AbortSignal.timeout(4500)});if(!r.ok)throw Error('http'+r.status);return r.json()};
const exact=u=>{try{let v=new URL(u);return v.hostname.replace(/^www\./,'')==='chatgpt.com'?v.pathname.replace(/\/$/,''):''}catch{return ''}};
function probe(wsUrl, method, params={}, timeoutMs=2300) {return new Promise(resolve=>{
 let ws,done=false,open=false;const st=performance.now();
 const finish=(x)=>{if(done)return;done=true;clearTimeout(timer);try{ws?.close()}catch{}resolve({method,elapsedMs:Math.round(performance.now()-st),open,...x})};
 const timer=setTimeout(()=>finish({ok:false,result:'timeout'}),timeoutMs);
 try{ws=new WebSocket(wsUrl);ws.addEventListener('open',()=>{open=true;try{ws.send(JSON.stringify({id:19,method,params}))}catch{finish({ok:false,result:'send_failed'})}});ws.addEventListener('message',e=>{try{let x=JSON.parse(e.data);if(x.id===19)finish({ok:!x.error,result:x.error?String(x.error.message).slice(0,150):'acknowledged'})}catch{finish({ok:false,result:'invalid_reply'})}});ws.addEventListener('error',()=>finish({ok:false,result:'ws_error'}))}catch{finish({ok:false,result:'open_error'})}
})}
async function main(){
 const [o,c,w]=await Promise.all([get(base+'/api/operator-lifecycle'),get(base+'/api/supervisor-watchdog/managed-chats?inspect=0'),get(base+'/api/supervisor-watchdog?detect=0')]);
 if(o.queuePaused!==true||w.config?.mode!=='off'||w.config?.allowAutonomousSend!==false)throw Error('autonomy_not_frozen');
 const chat=c.chats.find(x=>x.name==='Bridge');if(!chat||!exact(chat.url))throw Error('Bridge_unknown');
 const t=(await get('http://127.0.0.1:17410/json/list')).filter(x=>exact(x.url)===exact(chat.url)&&x.webSocketDebuggerUrl);
 if(t.length!==1)throw Error('Bridge_not_exactly_one_tab');
 const u=t[0].webSocketDebuggerUrl;
 const before=await probe(u,'Runtime.evaluate',{expression:'2+2',returnByValue:true,awaitPromise:false},1400);
 if(before.ok){console.log(JSON.stringify({preAlreadyResponsive:true,before}));return}
 const action=await probe(u,'Page.setWebLifecycleState',{state:'active'},3800);
 await new Promise(r=>setTimeout(r,750));
 const after=await probe(u,'Runtime.evaluate',{expression:'2+2',returnByValue:true,awaitPromise:false},2300);
 console.log(JSON.stringify({at:new Date().toISOString(),canary:'Bridge',method:'Page.setWebLifecycleState(active)',before,action,after,noNavigation:true,noReload:true,noSend:true}));
}
main().catch(e=>{console.log(JSON.stringify({error:String(e.message).slice(0,130)}));process.exitCode=1});
